package com.trampolim.api.career;
import java.util.*;import java.math.BigDecimal;import java.time.*;
import static com.trampolim.api.radar.RadarModel.*;
import com.trampolim.api.security.PlatformAccess;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class ProfessionalChallengeService {
 private final com.trampolim.api.radar.RadarBridge bridge;private final JdbcTemplate db;private final CompanyCareerService companies;private final PlatformAccess platform;
 public ProfessionalChallengeService(@Qualifier("empresasJdbcTemplate")JdbcTemplate db,CompanyCareerService companies,PlatformAccess platform,com.trampolim.api.radar.RadarBridge bridge){this.bridge=bridge;this.db=db;this.companies=companies;this.platform=platform;}
 public record Proposal(int expectedRevision,int estimatedMinutes,int participantLimit,boolean educationalOnly,boolean noProductiveUse,boolean authorRetainsRights,boolean voluntary,boolean noHiringGuarantee){}
 public record Decision(int expectedRevision,boolean approved,String reason,boolean safeguardsReviewed){}
 private void admin(String email){if(!platform.isSuperAdmin(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 private Map<String,Object> lock(long id,int revision){var rows=db.queryForList("SELECT * FROM company_challenges WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var r=rows.getFirst();if(((Number)r.get("revision")).intValue()!=revision)throw new ResponseStatusException(HttpStatus.CONFLICT,"O desafio mudou; consulte a revisão atual.");return r;}
 private void log(long id,String actor,String action,String reason){db.update("INSERT INTO company_challenge_moderation(challenge_id,actor,action,reason,revision) SELECT id,?,?,?,revision FROM company_challenges WHERE id=?",actor,action,reason,id);}
 @Transactional("empresasTransactionManager")public Map<String,Object> propose(String email,long id,Proposal p){companies.ownChallenge(email,id,true);if(p==null||p.estimatedMinutes()<5||p.estimatedMinutes()>120||p.participantLimit()<1||p.participantLimit()>10000||!p.educationalOnly()||!p.noProductiveUse()||!p.authorRetainsRights()||!p.voluntary()||!p.noHiringGuarantee())bad("Confirme todas as salvaguardas, estimativa de 5 a 120 minutos e limite de 1 a 10000 participantes.");var r=lock(id,p.expectedRevision());if(!r.get("status").equals("DRAFT")||r.get("review_status").equals("PENDING"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Use um rascunho ainda não enviado.");if(!((java.sql.Timestamp)r.get("deadline")).toInstant().isAfter(Instant.now()))bad("O prazo deve estar aberto.");if(!Boolean.TRUE.equals(db.queryForObject("SELECT verification_status='APPROVED' FROM companies WHERE id=?",Boolean.class,r.get("company_id"))))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Somente empresa aprovada pode propor desafios.");db.update("UPDATE company_challenges SET review_status='PENDING',estimated_minutes=?,participant_limit=?,safeguards_accepted=TRUE,revision=revision+1 WHERE id=?",p.estimatedMinutes(),p.participantLimit(),id);log(id,email,"PROPOSED","Empresa confirmou finalidade educacional, participação voluntária, sem uso produtivo, retenção de direitos pelo autor e ausência de garantia de contratação.");return companies.challenge(email,id);}
 public Map<String,Object> queue(String email,long before,int limit){admin(email);CareerRules.page(before,limit);return CareerRules.pageResult(db.queryForList("SELECT d.id,d.company_id,d.title,d.status,d.review_status,d.deadline,d.revision,c.trade_name FROM company_challenges d JOIN companies c ON c.id=d.company_id WHERE d.id<? ORDER BY d.id DESC LIMIT ?",before,limit+1),limit);}
 public Map<String,Object> inspect(String email,long id){admin(email);var r=db.queryForList("SELECT * FROM company_challenges WHERE id=?",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));r.put("skills",bridge.convert(bridge.read(r.get("skills")),Object.class));r.put("rubric",bridge.convert(bridge.read(r.get("rubric")),Object.class));r.put("moderationHistory",db.queryForList("SELECT action,reason,revision,created_at FROM company_challenge_moderation WHERE challenge_id=? ORDER BY id DESC LIMIT 50",id));return r;}
 @Transactional("empresasTransactionManager")public Map<String,Object> decide(String email,long id,Decision p){admin(email);if(p==null||text(p.reason(),2000).length()<20||p.approved()&&!p.safeguardsReviewed())bad("Registre justificativa clara e confirme revisão das salvaguardas para aprovar.");var r=lock(id,p.expectedRevision());if(!r.get("review_status").equals("PENDING"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Somente proposta pendente pode ser decidida.");long company=((Number)r.get("company_id")).longValue();if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM company_members m JOIN company_users u ON u.id=m.user_id WHERE m.company_id=? AND LOWER(u.email)=LOWER(?))",Boolean.class,company,email)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"A revisão deve ser independente da empresa proponente.");if(p.approved()&&(!Boolean.TRUE.equals(r.get("safeguards_accepted"))||!((java.sql.Timestamp)r.get("deadline")).toInstant().isAfter(Instant.now())||!Boolean.TRUE.equals(db.queryForObject("SELECT verification_status='APPROVED' FROM companies WHERE id=?",Boolean.class,company))))bad("A proposta precisa manter salvaguardas, empresa aprovada e prazo aberto.");db.update("UPDATE company_challenges SET review_status=?,revision=revision+1 WHERE id=?",p.approved()?"APPROVED":"REJECTED",id);log(id,email,p.approved()?"APPROVED":"REJECTED",p.reason().trim());return inspect(email,id);}
 @Transactional("empresasTransactionManager")public void suspend(String email,long id,int revision,String reason){admin(email);if(text(reason,2000).length()<20)bad("Informe justificativa de ao menos vinte caracteres.");lock(id,revision);db.update("UPDATE company_challenges SET review_status='REJECTED',status='CLOSED',revision=revision+1 WHERE id=?",id);log(id,email,"SUSPENDED",reason.trim());}
 public Map<String,Object> indicators(String email,long id){companies.ownChallenge(email,id,false);var r=db.queryForMap("SELECT count(*) AS received,count(*) FILTER(WHERE s.status='WITHDRAWN') AS withdrawn,count(*) FILTER(WHERE r.id IS NOT NULL AND r.revoked_at IS NULL AND s.status<>'WITHDRAWN') AS evaluated,count(*) FILTER(WHERE r.revoked_at IS NULL AND s.status<>'WITHDRAWN' AND r.score_percent>=(s.rubric->>'passPercent')::numeric) AS approved FROM company_challenge_submissions s LEFT JOIN company_challenge_reviews r ON r.receipt_id=s.receipt_id WHERE s.challenge_id=?",id);r.put("notice","Contagens deste desafio; não representam contratações, certificados formais ou classificação pública de pessoas.");return r;}
 public Map<String,Object> evidence(String key,CompanyCareerService.Receipt input){bridge.authorize(key);if(input==null||input.receiptId()==null||input.version()!=1)bad("Recibo inválido.");var rows=db.queryForList("SELECT s.challenge_id,s.status,r.id AS review_id,r.score_percent,r.reviewed_at,r.revoked_at,s.rubric,d.title,d.skills,d.review_status,c.trade_name,c.verification_status FROM company_challenge_submissions s JOIN company_challenges d ON d.id=s.challenge_id JOIN companies c ON c.id=d.company_id LEFT JOIN company_challenge_reviews r ON r.receipt_id=s.receipt_id WHERE s.receipt_id=?",input.receiptId());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var r=rows.getFirst();boolean valid=r.get("status").equals("REVIEWED")&&r.get("review_id")!=null&&r.get("revoked_at")==null&&r.get("review_status").equals("APPROVED")&&r.get("verification_status").equals("APPROVED")&&new BigDecimal(r.get("score_percent").toString()).compareTo(new BigDecimal(bridge.read(r.get("rubric")).path("passPercent").asText()))>=0;if(!valid)return Map.of("status","INVALID","formalCertificate",false);var out=new LinkedHashMap<String,Object>();out.put("status","ACTIVE");out.put("formalCertificate",false);out.put("recordType","COMPANY_ASSESSED_PROFESSIONAL_EVIDENCE");out.put("reviewId",r.get("review_id"));out.put("challengeId",r.get("challenge_id"));out.put("title",r.get("title"));out.put("issuer",r.get("trade_name"));out.put("scorePercent",r.get("score_percent"));out.put("skills",bridge.convert(bridge.read(r.get("skills")),List.class));out.put("criterion",bridge.convert(bridge.read(r.get("rubric")),Map.class));out.put("issuedAt",r.get("reviewed_at").toString());return out;}
 @Transactional("empresasTransactionManager")public void revokeReview(String email,long id,UUID receipt,String reason){companies.ownChallenge(email,id,true);if(text(reason,500).length()<20)bad("Informe justificativa de ao menos vinte caracteres.");if(db.update("UPDATE company_challenge_reviews SET revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP),revocation_reason=COALESCE(revocation_reason,?) WHERE receipt_id=? AND receipt_id IN (SELECT receipt_id FROM company_challenge_submissions WHERE challenge_id=?)",reason.trim(),receipt,id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);log(id,email,"RESULT_REVOKED",reason.trim());}
}
